// AuthRouteHandler.js
import React from 'react';
import { Route, Routes } from 'react-router-dom';
import { authRouteConfig } from '/authRouteConfig';  // Import the auth route config

const AuthRouteHandler = () => {
  return (
    <Routes>
      {authRouteConfig.map((route, index) => (
        <Route
          key={index}
          path={route.path}
          element={route.component}  // Render the component directly
        />
      ))}
    </Routes>
  );
};

export default AuthRouteHandler;
